{
  "root_causes": [
    {
      "service": "ts-train-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-train-service' AND (span_name LIKE '%SELECT%' OR span_name LIKE '%commit%') GROUP BY 1,2,3 UNION ALL SELECT 'norm', service_name, span_name, count(*), approx_quantile(duration/1e6,0.95) FROM normal_traces WHERE service_name='ts-train-service' AND (span_name LIKE '%SELECT%' OR span_name LIKE '%commit%') GROUP BY 1,2,3 ORDER BY 3,1", "claim": "Train-service DB SELECT spans went from about 1-2 ms p95 to about 7 s p95; Transaction.commit from about 1 ms to 16.6 s."},
        {"kind": "trace", "sql": "SELECT p.service_name AS caller, c.service_name AS callee, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(p.duration/1e6,0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.service_name <> p.service_name AND c.service_name IN ('ts-train-service','ts-basic-service','ts-travel-service','ts-travel2-service','ts-route-plan-service','ts-travel-plan-service','ts-preserve-service') GROUP BY 1,2 ORDER BY callee_p95_ms DESC", "claim": "Callers of train-service (basic, travel-plan, ui-dashboard) show p95 latency matching the train callee's latency, so the delay is inherited."},
        {"kind": "metric", "sql": "SELECT 'abn' p, metric, attr_source_workload, attr_destination_workload, round(avg(value),2) v, count(*) n FROM abnormal_metrics_sum WHERE metric LIKE 'hubble%drop%' AND (attr_source_workload LIKE '%train-service%' OR attr_destination_workload LIKE '%train-service%' OR attr_destination_workload LIKE 'mysql%') GROUP BY 1,2,3,4", "claim": "No drop or retransmit signal on train-service network connections; the slowdown is inside its DB calls, not the wire."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-train-service", "to": "ts-basic-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name AS caller, c.service_name AS callee, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(p.duration/1e6,0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.service_name <> p.service_name AND c.service_name IN ('ts-train-service','ts-basic-service','ts-travel-service','ts-travel2-service','ts-route-plan-service','ts-travel-plan-service','ts-preserve-service') GROUP BY 1,2 ORDER BY callee_p95_ms DESC", "claim": "basic-service calling train-service: about 8.3 s p95 on the callee, matching the caller's 8.3 s."}]},
    {"from": "ts-train-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name AS caller, c.service_name AS callee, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(p.duration/1e6,0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.service_name <> p.service_name AND c.service_name IN ('ts-train-service','ts-basic-service','ts-travel-service','ts-travel2-service','ts-route-plan-service','ts-travel-plan-service','ts-preserve-service') GROUP BY 1,2 ORDER BY callee_p95_ms DESC", "claim": "travel-plan-service calling train-service: about 15 s p95 on the callee, matching the caller's 15 s."}]},
